903	void i40e_xsk_clean_rx_ring(struct i40e_ring *rx_ring)
904	{
905		u16 i;
906	
907		for (i = 0; i < rx_ring->count; i++) {
908			struct i40e_rx_buffer *rx_bi = &rx_ring->rx_bi[i];
909	
910			if (!rx_bi->addr)
911				continue;
912	
913			xsk_umem_fq_reuse(rx_ring->xsk_umem, rx_bi->handle);
914			rx_bi->addr = NULL;
915		}
916	}
